{
  "name": "海洋光谱仪",
  "name_en": "Ocean spectrometer",
  "manufacturer": "Ocean Insight",
  "description": "海洋光谱仪是一类用于测量光强随波长分布的实验室光谱设备，常用于采集样品的发射、透射、反射或其他光学光谱信号。该类仪器适合基础光谱测量、过程监测和通用光学实验。",
  "description_en": "An ocean spectrometer is a laboratory optical spectrometer used to measure light intensity as a function of wavelength. It is commonly used to acquire emission, transmission, reflection, or other optical spectra from samples in general spectroscopy experiments and routine measurement workflows.",
  "actions": [
    {
      "action_name": "auto-connect",
      "description": "连接到光谱仪。",
      "description_en": "Connect to the spectrometer."
    },
    {
      "action_name": "auto-acquire_data",
      "description": "采集一次光谱数据。",
      "description_en": "Acquire a spectrum."
    },
    {
      "action_name": "auto-scans_to_average",
      "description": "设置每次采集时参与平均的扫描次数。",
      "description_en": "Set the number of scans to average for each acquisition."
    }
  ],
  "tag_hints": [
    "optical spectroscopy",
    "spectral acquisition",
    "USB spectrometer",
    "scan averaging",
    "general lab spectroscopy"
  ]
}

